const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, clients, eventActive=false, selected=null, filter='unresolved', view='list', topK=12;
const key='heat-check-in-demo-v1';
const today='2026-09-19'; // Fixed scenario clock keeps demo freshness reproducible.
const fields={cooling:'Working cooling',backup:'Backup cool location',transport:'Transportation needed',affordability:'Cooling cost concern',clinical:'Question for a clinician',contact:'Preferred contact'};
const options={cooling:['unknown','working','broken','unavailable'],backup:['unknown','yes','no'],transport:['unknown','needed','no'],affordability:['unknown','yes','no'],clinical:['unknown','yes','no']};
const ntaZips={BX0101:['10451','10454','10455'],BX0102:['10451','10455','10456','10459'],BX0201:['10455','10459','10474'],BX0202:['10455','10456','10459']}; // real NTA-ZIP crosswalk, nychealth/EHDP-data
const NTA_GEO={BX0101:[40.80752,-73.91724],BX0102:[40.81826,-73.91285],BX0201:[40.81086,-73.88498],BX0202:[40.82097,-73.89656]}; // real centroids, NYC Open Data 9nt8-h7nd (2020 NTAs)
let map,markers={};
// Leaflet positions the divIcon wrapper itself via inline style.transform, so
// our hover-scale CSS must target an inner element instead — animating the
// same node Leaflet moves would fight its translate3d and get overridden.
function pinIcon(affected){return L.divIcon({className:'hc-pin-wrap',html:`<div class="leaflet-pin${affected?' affected':''}"></div>`,iconSize:[14,14]})}
function initMap(){
 if(typeof L==='undefined'||map||!data)return;
 map=L.map('leaflet-map',{scrollWheelZoom:false}).setView([40.813,-73.905],13);
 L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap contributors'}).addTo(map);
 data.hvi.forEach(r=>{const pos=NTA_GEO[r.NTACode];if(!pos)return;
  const m=L.marker(pos,{icon:pinIcon(false)}).addTo(map);
  m.bindPopup(`<h4>${esc(r.GEONAME)}</h4><div class="stat-row"><span>HVI rank</span><b>${esc(r.HVI_RANK)}/5</b></div><div class="stat-row"><span>Greenspace</span><b>${Number(r.GREENSPACE).toFixed(1)}%</b></div><div class="stat-row"><span>Households with AC</span><b>${Number(r.PCT_HOUSEHOLDS_AC).toFixed(1)}%</b></div>`);
  markers[r.NTACode]=m;});
}
function updateMapMarkers(){
 if(!map)return;
 data.hvi.forEach(r=>{const m=markers[r.NTACode];if(!m)return;
  const affected=eventActive&&(ntaZips[r.NTACode]||[]).some(z=>data.event.zips.includes(z));
  m.setIcon(pinIcon(affected));});
}
function hoverNta(code,on){
 const m=markers[code];if(!m)return;
 const wrap=m.getElement();if(!wrap)return;
 const pin=wrap.querySelector('.leaflet-pin');if(!pin)return;
 pin.classList.toggle('hover',on);
 wrap.style.zIndex=on?1000:'';
}
const HEAT_TIERS=[{name:'Minimal',color:'#22c55e'},{name:'Low',color:'#a3e635'},{name:'Moderate',color:'#facc15'},{name:'High',color:'#fb923c'},{name:'Severe',color:'#ef4444'},{name:'Extreme',color:'#7f1d4b'}];
function renderHeatRisk(){
 const hr=data.heat_risk, slot=$('#heat-risk');
 if(!hr||!hr.available){slot.innerHTML='<div class="heat-risk-card unavailable">Recent NYC heat reading unavailable right now (live NOAA fetch failed at build time). Not treated as safe.</div>';return}
 const idx=HEAT_TIERS.findIndex(t=>t.name===hr.band);
 slot.innerHTML=`<details class="heat-risk-card" open><summary><span class="hr-swatch" style="background:${hr.color}"></span><span class="hr-headline">Recent NYC heat: <b>${esc(hr.band)}</b></span><span class="hr-caret">▾</span></summary><div class="hr-body"><p class="hr-reading"><b>${hr.tmax_f}°F</b> recorded max · ${esc(hr.date)} · ${esc(hr.station)}</p><div class="hr-bar">${HEAT_TIERS.map(t=>`<span class="hr-seg" style="background:${t.color}"></span>`).join('')}<span class="hr-marker" style="left:${(idx+0.5)/HEAT_TIERS.length*100}%"></span></div><div class="hr-labels">${HEAT_TIERS.map(t=>`<span class="${t.name===hr.band?'current':''}">${t.name}</span>`).join('')}</div><p class="tiny">${esc(hr.source)}. Independent of the simulated advisory above — this is real recent weather, not a forecast and not tied to this demo's event. ${esc(hr.threshold_note)} <a href="${hr.threshold_source_url}" target="_blank" rel="noreferrer">NWS OKX</a> · <a href="${hr.source_url}" target="_blank" rel="noreferrer">NOAA</a>.</p></div></details>`;
}
const stale=f=>!f?.verified_at || (new Date(today)-new Date(f.verified_at))/86400000>30;
const openTasks=c=>c.tasks.filter(t=>t.status!=='Support verified');
const needs=(c,k)=>!c[k]||c[k].value==='unknown'||stale(c[k]);
function band(c){if(openTasks(c).length||['broken','unavailable'].includes(c.cooling.value)||c.transport.value==='needed'||c.affordability.value==='yes'||c.clinical.value==='yes')return 'unresolved';if(Object.keys(fields).some(k=>needs(c,k))||c.consent.value!=='yes'||['Unreachable','Declined'].includes(c.outcome))return 'review';return 'confirmed'}
const labels={unresolved:'Contact first',review:'Needs verification',confirmed:'Plan confirmed'};
function reasons(c){const r=[];if(['broken','unavailable'].includes(c.cooling.value))r.push('Cooling unavailable — support not verified');if(c.transport.value==='needed')r.push('Transportation is not yet secured');if(c.affordability.value==='yes')r.push('Cooling affordability concern');if(c.clinical.value==='yes')r.push('Clinical question awaiting review');if(!r.length&&openTasks(c).length)r.push('Follow-up is still open');if(needs(c,'cooling'))r.push('Cooling plan is unknown or outdated');if(c.outcome==='Unreachable')r.push('Previous contact attempt was unsuccessful');if(!r.length&&band(c)==='review')r.push('Plan or contact permissions need verification');return r.length?r:['Cooling plan and required support confirmed']}
function completeness(c){const n=Object.keys(fields).filter(k=>!needs(c,k)).length;return `${n}/6 fields recently verified`}
function save(){try{localStorage.setItem(key,JSON.stringify({clients,eventActive}));return true}catch{toast('Could not save on this device. Keep this page open and retry.');return false}}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),4500)}
function modal(title,body){$('#info-title').textContent=title;$('#info-body').innerHTML=body;$('#info').showModal()}
function fact(c,k){return `<div class="fact">${esc(fields[k]||k)}: <b>${esc(c[k].value)}</b><small>${esc(c[k].source)} · ${esc(c[k].verified_at||'Not verified')}</small></div>`}
function render(){
 $('#event').innerHTML=eventActive?`<div class="event"><span><b>● Simulated heat advisory</b> · September 20–22, 2026</span><span>Demo ZIP coverage: 10454, 10455 · Not an official alert</span></div>`:`<div class="event inactive"><span><b>Seasonal readiness</b> · No advisory activated</span><span>Check plans now, or simulate an event.</span></div>`;
 $('#simulate').textContent=eventActive?'End demo advisory':'Simulate advisory';
 renderHeatRisk();
 $('#neighborhoods').innerHTML=data.hvi.map(r=>{const affected=eventActive&&(ntaZips[r.NTACode]||[]).some(z=>data.event.zips.includes(z));return `<div class="neighborhood ${selected&&clients.find(c=>c.id===selected)?.nta.value===r.NTACode?'selected':''} ${affected?'affected':''}" data-nta="${esc(r.NTACode)}" role="button" tabindex="0"><div><b>${esc(r.GEONAME)}</b>${affected?' <span class="advisory-tag">In advisory</span>':''}<br><small>Greenspace ${Number(r.GREENSPACE).toFixed(1)}% · Households with AC ${Number(r.PCT_HOUSEHOLDS_AC).toFixed(1)}%</small></div><span class="hvi">HVI ${esc(r.HVI_RANK)}/5</span></div>`}).join('');
 updateMapMarkers();
 document.querySelectorAll('[data-nta]').forEach(el=>{const open=()=>{const m=markers[el.dataset.nta];if(m&&map){map.panTo(m.getLatLng());m.openPopup()}};el.onclick=open;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 if(selected)renderCard();else if(view==='tasks')renderTasks();else renderList();
}
function renderList(){
 const all=clients.filter(c=>!eventActive||data.event.zips.includes(c.zip.value));
 const list=all.filter(c=>band(c)===filter).slice(0,topK);
 const counts=Object.fromEntries(Object.keys(labels).map(k=>[k,all.filter(c=>band(c)===k).length]));
 $('#work').innerHTML=`<div class="work-head"><span class="eyebrow">ACTIVE CASELOAD</span><h2>Who needs a check-in?</h2><p>${all.length} synthetic clients · Open a person to see what changed and what to ask.</p></div><div class="queue-overview"><button class="queue-metric urgent ${filter==='unresolved'?'active':''}" data-filter="unresolved"><b>${counts.unresolved}</b><span>Action today</span></button><button class="queue-metric ${filter==='review'?'active':''}" data-filter="review"><b>${counts.review}</b><span>Needs verification</span></button><button class="queue-metric confirmed ${filter==='confirmed'?'active':''}" data-filter="confirmed"><b>${counts.confirmed}</b><span>Plans confirmed</span></button></div><div class="list-controls"><label>Show <select id="topk">${[4,8,12].map(n=>`<option ${n===topK?'selected':''}>${n}</option>`).join('')}</select></label><button id="print">Print call sheet</button></div>${list.length?list.map(c=>`<button class="client" data-client="${c.id}" data-nta="${esc(c.nta.value)}"><div class="client-top"><strong>${c.id} ↗</strong><span class="band ${filter}">${labels[filter]}</span></div><p>${esc(reasons(c).slice(0,2).join(' · '))}</p><small>${esc(c.cohort.value)} · Age ${esc(c.age.value)} · ${esc(completeness(c))}<br>Reach: ${c.outcome==='Unreachable'?'retry needed':'not scored'} · ${esc(c.owner||'Unclaimed')} · Synthetic</small></button>`).join(''):'<div class="empty">No clients in this group. Other groups remain available.</div>'}<div class="data-note">Demo workflow rules · No validated clinical risk or confidence score. Scenario clock: ${today}. Showing ${list.length} of ${counts[filter]} in this group.</div>`;
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});
 document.querySelectorAll('[data-client]').forEach(b=>{b.onclick=()=>{selected=b.dataset.client;render();$('#back').focus()};b.onmouseenter=b.onfocus=()=>hoverNta(b.dataset.nta,true);b.onmouseleave=b.onblur=()=>hoverNta(b.dataset.nta,false)});
 $('#topk').onchange=e=>{topK=Number(e.target.value);render()};$('#print').onclick=()=>window.print();
}
function renderCard(){
 const c=clients.find(c=>c.id===selected), r=data.hvi.find(r=>r.NTACode===c.nta.value);
 const unknown=Object.keys(fields).filter(k=>needs(c,k));
 $('#work').innerHTML=`<div class="card"><button class="back" id="back">← Back to call list</button><div class="card-title"><h2>${c.id}</h2><button id="claim">${c.owner?'Claimed · Demo worker':'Claim client'}</button></div><span class="band ${band(c)}">${labels[band(c)]}</span> <span class="pill">Synthetic client</span> <span class="pill">${esc(c.cohort.value)} · Age ${esc(c.age.value)}</span><div class="reason-box"><h3>Why this priority?</h3><p><strong>Why now</strong>${eventActive?'The client’s demo ZIP is included in this simulated advisory.':'Seasonal readiness review; no active advisory.'}</p><p><strong>Why this person</strong>${esc(reasons(c).join('. '))}.</p><p><strong>Evidence</strong>Cooling: ${esc(c.cooling.value)} · ${esc(c.cooling.source)} · ${esc(c.cooling.verified_at||'Not verified')}<br>${completeness(c)}. Verification coverage is not clinical confidence.</p><p><strong>Still uncertain</strong>${unknown.length?unknown.map(k=>fields[k]).join(', '):'No missing readiness fields; review any remaining tasks.'}</p><p><strong>What changes this priority?</strong>Verify a workable cooling plan, resolve required support, and refresh missing information.</p><details><summary>View demo rules and area context</summary><p>Unresolved needs first → missing or outdated plans → confirmed plans. Within each group, fixture order is stable; it does not imply a clinical ranking.</p><p>${esc(r?.GEONAME)}: HVI ${esc(r?.HVI_RANK)}/5. Area context only; not used as evidence that this client lacks AC.</p></details></div><div class="factgrid">${fact(c,'cooling')}${fact(c,'contact')}</div><h3 class="section-title">Follow-up tasks · ${openTasks(c).length} open</h3>${c.tasks.length?c.tasks.map(t=>`<div class="fact ${t.status==='Support verified'?'':'open'}">${esc(t.type)}: <b>${esc(t.status)}</b><small>${esc(t.owner)} · due ${esc(t.due)}</small></div>`).join(''):'<p class="tiny">No follow-up tasks yet.</p>'}<h3 class="section-title">Contact permission</h3><label>Consent opt-in <select id="consent">${['unknown','yes','no'].map(v=>`<option ${c.consent.value===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="tiny">Confirm permission before outreach. This demo does not place calls or send messages.</p><form id="checkin"><h3 class="section-title">Your check-in questions</h3><p class="tiny">${unknown.length} fields need verification. Recently verified answers are collapsed; expand to update a changed situation.</p>${Object.keys(fields).map(k=>`<${needs(c,k)?'div':'details'} class="question">${needs(c,k)?'':`<summary>${fields[k]}: ${esc(c[k].value)} · verified ${esc(c[k].verified_at)}</summary>`}<label>${fields[k]}${k==='contact'?`<input name="${k}" value="${esc(c[k].value)}" placeholder="Demo contact preference only">`:`<select name="${k}">${options[k].map(v=>`<option ${c[k].value===v?'selected':''}>${v}</option>`).join('')}</select>`}</label></${needs(c,k)?'div':'details'}>`).join('')}<label>Check-in note — synthetic content only<textarea name="note">${esc(c.notes)}</textarea></label><h3 class="section-title">Suggested next actions</h3><div id="next-actions"></div><label>Call outcome<select name="outcome"><option>Reached</option><option>Unreachable</option><option>Declined</option></select></label><label>Follow-up due date<input type="date" name="due" value="2026-09-20" required></label><div class="call-footer"><button type="submit" class="primary">Save check-in & actions</button></div></form><details class="history"><summary>Activity history · ${c.history.length}</summary>${c.history.map(h=>`<p>${esc(h.at)} — ${esc(h.action)}</p>`).join('')||'<p>No recorded activity.</p>'}</details></div>`;
 $('#back').onclick=()=>{selected=null;view='list';render()};
 $('#claim').onclick=()=>{c.owner='Demo worker';c.history.push({at:new Date().toISOString(),action:'Claimed by Demo worker'});save();render()};
 const form=$('#checkin');
 function preview(){const f=new FormData(form);$('#next-actions').innerHTML=data.decision_table.filter(d=>d.values.includes(f.get(d.field))).map(d=>`${esc(d.task)} → ${esc(d.owner)}`).join('<br>')||'No support task suggested by the current answers.';}
 form.onchange=preview;preview();
 form.onsubmit=e=>{e.preventDefault();if(!c.owner){toast('Claim this client before recording a check-in.');return}const consent=$('#consent').value;c.consent={value:consent,source:'Demo worker confirmation',verified_at:today};if(consent!=='yes'){c.outcome='Permission review';ensureTask(c,'Contact permission review','Supervisor','2026-09-20');save();render();toast('Permission review saved. No outreach recorded.');return}
 const f=new FormData(form), outcome=f.get('outcome');c.outcome=outcome;c.notes=f.get('note');
 if(outcome==='Reached'){for(const k of Object.keys(fields)){const value=String(f.get(k));if(value!=='unknown')c[k]={value,source:'Demo check-in confirmation',verified_at:today}}
 for(const d of data.decision_table)if(d.values.includes(c[d.field].value))ensureTask(c,d.task,d.owner,f.get('due'));
 }else ensureTask(c,outcome==='Unreachable'?'Retry / escalation':'Contact preference review',outcome==='Unreachable'?'Care navigator':'Supervisor',f.get('due'));
 c.history.push({at:new Date().toISOString(),action:`${outcome} — check-in saved; proposed task owners require review in Follow-up`});save();render();toast('Check-in saved. Review task owners and verify support in Follow-up.');};
}
function ensureTask(c,type,owner,due){if(!c.tasks.some(t=>t.type===type&&t.status!=='Support verified'))c.tasks.push({type,owner,due,status:'Requested',evidence:''})}
function renderTasks(){
 $('#work').innerHTML=`<div class="work-head"><h2>Follow through on support</h2><p>Accepted is not completed. Verify support before closing a need.</p></div>${clients.flatMap(c=>c.tasks.map((t,i)=>`<form class="task" data-task="${c.id}:${i}"><h3>${esc(t.type)} <span class="pill">${c.id}</span></h3><label>Owner<select name="owner">${['Housing staff','Resource partner','Care navigator','Clinician','Supervisor'].map(o=>`<option ${o===t.owner?'selected':''}>${o}</option>`).join('')}</select></label><label>Due<input type="date" name="due" value="${esc(t.due)}" required></label><label>Status<select name="status">${['Requested','Accepted','In progress','Blocked','Support verified'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></label><label>Verification evidence / blocker<input name="evidence" value="${esc(t.evidence)}" placeholder="How was support confirmed?"></label><button type="submit">Save task</button></form>`)).join('')||'<p class="empty">No follow-up tasks.</p>'}`;
 document.querySelectorAll('[data-task]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const [id,n]=form.dataset.task.split(':'),c=clients.find(c=>c.id===id),t=c.tasks[Number(n)],f=new FormData(form);if(['Support verified','Blocked'].includes(f.get('status'))&&!String(f.get('evidence')).trim()){toast('Add verification evidence or a blocker before saving.');return}Object.assign(t,Object.fromEntries(f));if(t.status==='Support verified'){const mapping={'Cooling support':['cooling','working'],'Transportation':['transport','no'],'Cooling affordability':['affordability','no'],'Clinical question':['clinical','no']};if(mapping[t.type]){const [k,v]=mapping[t.type];c[k]={value:v,source:'Demo support verification',verified_at:today}}}c.history.push({at:new Date().toISOString(),action:`${t.type}: ${t.status}; ${t.evidence}`});save();render();toast('Task updated; client priority recalculated.');});
}
function route(){const work=location.hash==='#workspace';$('#home').hidden=work;$('#workspace').hidden=!work;document.body.dataset.route=work?'workspace':'home';window.scrollTo({top:0,behavior:'instant'});if(work){initMap();setTimeout(()=>map&&map.invalidateSize(),0)}}
$('#close-info').onclick=()=>$('#info').close();window.onhashchange=route;
$('#simulate').onclick=()=>{eventActive=!eventActive;save();render()};
$('#reset').onclick=()=>{if(confirm('Reset all demo check-ins and tasks on this device?')){clients=structuredClone(data.clients);eventActive=false;selected=null;save();render();toast('Demo reset.')}};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;selected=null;render()});
$('#guide-button').onclick=()=>modal('Your check-in guide',`<p><b>1. Understand the priority.</b> Open a client to see the individual evidence, missing information, and separately labeled area context.</p><p><b>2. Claim and check permission.</b> Only then record the check-in. Unknown answers stay unknown.</p><p><b>3. Follow up.</b> An accepted referral remains open until support is verified. Unreachable clients retain a retry task.</p><p class="tiny">Static workflow guide, not a connected AI assistant. Decision-table actions are demo configuration awaiting practitioner review.</p>`);
$('#sources').onclick=()=>modal('Data & provenance',`<p><b>Real public data:</b> four South Bronx neighborhoods from the repository’s ${data.hvi_total_rows}-row <a href="${data.hvi_source}" target="_blank" rel="noreferrer">HVI snapshot</a>. The map is an OpenStreetMap area overview, not an HVI polygon overlay.</p><p><b>Historical observations:</b> ${data.heat.length} daily 2024 records from the cached <a href="${data.heat_source}" target="_blank" rel="noreferrer">NYC heat ED snapshot</a>. Citywide, not SMI-specific or a current advisory.</p><p><b>Synthetic:</b> all clients, assignments, ZIP coverage, consent, needs, and advisory details are project-created fixtures. The official clinical dataset has not been supplied.</p><p><b>Storage:</b> demo edits are kept in this browser only. No calls, messages, AI requests, or EHR updates are sent. Reset demo clears edits.</p><p><b>Pending:</b> validated weighted scores, calibrated confidence, official client adapter, live advisories, and verified ZIP–NTA geography.</p>`);
document.querySelectorAll('[data-open-sources]').forEach(button=>button.onclick=()=>$('#sources').click());
try{data=await fetch('data/demo.json').then(r=>{if(!r.ok)throw Error('data');return r.json()});clients=structuredClone(data.clients);try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.clients)&&saved.clients.length===data.clients.length && saved.clients.every((c,i)=>c.id===data.clients[i].id)){clients=saved.clients;eventActive=!!saved.eventActive}}catch{}
 const vals=data.heat.map(r=>Number(r.HEAT_ED_VISIT_COUNT));const max=Math.max(...vals,1);$('#heat-chart').innerHTML=`<p>Heat-related ED visits · Citywide daily counts</p><svg viewBox="0 0 500 100" role="img" aria-label="Historical daily heat-related emergency department visit counts during 2024"><polyline fill="none" stroke="#1769d2" stroke-width="2" points="${vals.map((v,i)=>`${i*500/(vals.length-1)},${95-v/max*85}`).join(' ')}"/></svg><div class="tiny">May–September 2024 · Daily maximum ${max} visits · Not a current alert</div>`;
 render();route();
 if(document.modelContext?.registerTool)document.modelContext.registerTool({name:'read_call_list',description:'Read the currently stored synthetic outreach list and explainable groups.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('Expected empty object');return clients.map(c=>({id:c.id,group:band(c),reasons:reasons(c)}))}});
}catch(e){$('#work').innerHTML='<p class="empty">Could not load demo data. Reload this page from the local server.</p>';toast('Demo data could not be loaded.');console.error(e)}
